types.text:
interface ButtonActivationEvent {
  readonly type: 'activate';
  readonly pointerType: ButtonPointerType;
  readonly target: HTMLButtonElement;
}

interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};

type MenuItemOwnProps = {
  id: string;
  textValue?: string;
  disabled?: boolean;
  onAction?: () => void;
  shouldCloseOnSelect?: boolean;
};

type MenuListOwnProps = {
  items?: MuxUIItems;
  disabled?: boolean;
  shouldCloseOnSelect?: boolean;
  onAction?: (item?: MuxUICollectionItem) => void;
  onSelect?: (item?: MuxUICollectionItem) => void;
};

type MenuListProps = MenuListOwnProps & {
  children?: React.ReactNode;
  className?: string;
} & {
  'aria-label'?: string;
  'aria-labelledby'?: string;
};

type MenuOwnProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
  shouldCloseOnSelect?: boolean;
  onAction?: (item?: MuxUICollectionItem) => void;
  onSelect?: (item?: MuxUICollectionItem) => void;
};

type MenuPopupOwnProps = {
  placement?: MuxUIPlacement;
  offset?: number;
  crossOffset?: number;
  shouldFlip?: boolean;
  containerPadding?: number;
  modal?: boolean;
};

type MenuPopupProps = React.HTMLAttributes<HTMLDivElement> & MenuPopupOwnProps & {
  anchorRef?: React.RefObject<Element | null>;
};

type MenuProps = MenuListOwnProps & {
  children?: React.ReactNode;
  className?: string;
} & MuxUIAriaAccessibleName;

type MenuSectionOwnProps = {
  title?: React.ReactNode;
};

type MenuSubmenuOwnProps = {
  delay?: number;
};

type MenuSubmenuProps = MenuSubmenuOwnProps & {
  children: React.ReactNode;
};

type MenuTriggerOwnProps = {
  disabled?: boolean | undefined;
  onActivate?: (event: ButtonActivationEvent) => void;
};
